<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue';import StudentSearchPage from './pages/StudentSearchPage.vue';import StudentEditPage from './pages/StudentEditPage.vue';import ModalDialog from './components/ModalDialog.vue';import {useStudentSearch} from './composables/useStudentSearch';import {useStudentEditor} from './composables/useStudentEditor';import {useDirtyGuard} from './composables/useDirtyGuard';import {confirmation,answerConfirmation} from './composables/useConfirmation';
const search=useStudentSearch(),editor=useStudentEditor(),editing=ref(false),menu=ref(false),canLeave=useDirtyGuard(editor.dirty);
async function open(id:string|null){const b=search.bootstrap.value;if(!b||search.busy.value||editor.busy.value)return;if(!await editor.load(id,b.contextId))return;if(editor.data.value){menu.value=false;editing.value=true;history.pushState({editing:true},'',id?`/students/${encodeURIComponent(id)}`:'/students/new');}}
async function back(saved=false){if(editor.busy.value)return;if(!saved&&!await canLeave())return;editing.value=false;editor.data.value=null;history.replaceState({},'','/students');await search.resume();}
const editorPath=()=>editor.data.value?.studentId?`/students/${encodeURIComponent(editor.data.value.studentId)}`:'/students/new';
const pop=async()=>{if(editing.value&&editor.busy.value){history.pushState({editing:true},'',editorPath());return;}if(editing.value){if(await canLeave())void back(true);else history.pushState({editing:true},'',editorPath());}};
onMounted(async()=>{await search.initialize();history.replaceState({},'','/students');window.addEventListener('popstate',pop);});onUnmounted(()=>window.removeEventListener('popstate',pop));
</script>
<template><header><strong>学生管理システム</strong><span>利用者 {{search.bootstrap.value?.user||'未認証'}}　業務日 {{search.bootstrap.value?.businessDate||'－'}}</span></header><main><section v-if="menu"><h1>学生管理メニュー</h1><div class="actions"><button @click="menu=false">学生検索</button><button v-if="search.bootstrap.value?.permissions.create" @click="open(null)">新規登録</button></div></section><StudentSearchPage v-else-if="!editing" :state="search" @open="open" @menu="menu=true"/><StudentEditPage v-else :state="editor" @back="back()" @saved="back(true)"/></main><ModalDialog v-if="confirmation" title="変更破棄の確認" label-id="discard-title" @cancel="answerConfirmation(false)"><p>{{confirmation.message}}</p><div class="dialog-actions"><button type="button" data-cancel @click="answerConfirmation(false)">取消</button><button type="button" class="primary" @click="answerConfirmation(true)">変更を破棄する</button></div></ModalDialog></template>
